const raw = $("Webhook").first().json;
const cfg = $("Configuración").first().json;

const data = raw.body?.body?.data || raw.body?.data || {};
const remoteJid = data.key?.remoteJid || '';
const participant = data.key?.participant || '';
const isGroup = String(remoteJid).endsWith('@g.us');

const message = data.message || {};

function findDocumentMessage(message) {
  if (!message || typeof message !== 'object') return null;
  if (message.documentMessage) return message.documentMessage;
  if (message.documentWithCaptionMessage?.message?.documentMessage) return message.documentWithCaptionMessage.message.documentMessage;
  if (message.viewOnceMessage?.message?.documentMessage) return message.viewOnceMessage.message.documentMessage;
  if (message.ephemeralMessage?.message?.documentMessage) return message.ephemeralMessage.message.documentMessage;
  if (message.ephemeralMessage?.message?.documentWithCaptionMessage?.message?.documentMessage) {
    return message.ephemeralMessage.message.documentWithCaptionMessage.message.documentMessage;
  }
  return null;
}

const documentMessage = findDocumentMessage(message);
const hasDocumentMessage = !!documentMessage;

const messageText =
  message?.conversation ||
  message?.extendedTextMessage?.text ||
  message?.imageMessage?.caption ||
  message?.videoMessage?.caption ||
  raw.body?.body?.body?.test ||
  '';

const originalQuestion = String(messageText || '').trim();
const hasGroupPrefix = /^(?:\/tr\b|tr\b)/i.test(originalQuestion);

const normalize = (value = '') =>
  String(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();

const normalizedOriginal = normalize(originalQuestion);

const mentionedJid =
  message?.extendedTextMessage?.contextInfo?.mentionedJid ||
  message?.imageMessage?.contextInfo?.mentionedJid ||
  message?.videoMessage?.contextInfo?.mentionedJid ||
  [];

const mentionText =
  message?.extendedTextMessage?.contextInfo?.participant ||
  message?.extendedTextMessage?.contextInfo?.stanzaId ||
  '';

const hasMention =
  (Array.isArray(mentionedJid) && mentionedJid.length > 0) ||
  /@\d{5,}/.test(originalQuestion) ||
  Boolean(mentionText);

const mentionsTrelloWord = /\btrello\b/i.test(originalQuestion);

const allowedGroupJid = cfg.allowedGroupJid || 'REEMPLAZAR_POR_TU_GRUPO@g.us';
const boardId = cfg.boardId || '5ff2d7873b288c34fbc1b918';
const allowedParticipantsCsv = cfg.allowedParticipantsCsv || '';

const allowedParticipants = String(allowedParticipantsCsv)
  .split(/[,;\n]/)
  .map(item => item.trim())
  .filter(Boolean);

const hasWhitelist = allowedParticipants.length > 0 &&
  !allowedParticipants.some(item => item.startsWith('REEMPLAZAR_'));

const normalizedAllowedParticipants = allowedParticipants.map(item => item.toLowerCase());
const normalizedParticipant = String(participant || '').toLowerCase();

const isAllowedGroup = isGroup && remoteJid === allowedGroupJid;
const isAllowedParticipant = !hasWhitelist || normalizedAllowedParticipants.includes(normalizedParticipant);
const likelyForBot = mentionsTrelloWord || hasMention;

const shouldRespond = !hasDocumentMessage && isAllowedGroup && hasGroupPrefix && isAllowedParticipant;
const shouldWarn = !hasDocumentMessage && isAllowedGroup && !hasGroupPrefix && likelyForBot && isAllowedParticipant;
const shouldUnauthorized = !hasDocumentMessage && isAllowedGroup && hasGroupPrefix && !isAllowedParticipant;

const question = shouldRespond
  ? originalQuestion.replace(/^(?:\/tr\b|tr\b)\s*/i, '').trim()
  : originalQuestion;

const replyTarget = isGroup ? remoteJid : String(remoteJid || '').split('@')[0];

return [
  {
    json: {
      ...raw,
      boardId,
      allowedGroupJid,
      allowedParticipantsCsv,
      allowedParticipants,
      hasWhitelist,
      originalQuestion,
      question,
      normalizedQuestion: normalize(question),
      normalizedOriginal,
      remoteJid,
      participant,
      isGroup,
      isAllowedGroup,
      isAllowedParticipant,
      hasDocumentMessage,
      shouldRespond,
      shouldWarn,
      shouldUnauthorized,
      usedPrefix: hasGroupPrefix,
      hasMention,
      mentionsTrelloWord,
      replyTarget,
    },
  },
];

const req = $("Normalizar entrada").first().json;

let output = '';

if (req.shouldUnauthorized) {
  output = 'No tienes permiso para usar este asistente en este grupo.';
} else {
  output = `Para usar el asistente en este grupo, empieza con /tr o tr.\n\nPrueba por ejemplo:\n- tr ayuda\n- tr listas\n- tr tarjetas en progreso con etiqueta urgente\n- tr tarjetas que vencen hoy`;
}

return [
  {
    json: {
      number: req.replyTarget,
      output,
    },
  },
];

const req = $("Normalizar entrada").first().json;
const question = req.normalizedQuestion || '';
const lists = $input.all().map(item => item.json);

const normalize = (value = '') =>
  String(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();

const q = normalize(question);

const explicitMatches = lists.filter(list => {
  const name = normalize(list.name);
  return name && q.includes(name);
});

const semanticBuckets = [
  {
    keywords: ['pendiente', 'pendientes', 'backlog', 'por hacer', 'por-hacer', 'todo', 'to do', 'abierto', 'abierta', 'nueva', 'nuevas'],
    listTerms: ['pendiente', 'backlog', 'por hacer', 'por-hacer', 'todo', 'to do', 'abierto', 'idea', 'ideas', 'nueva', 'nuevas'],
  },
  {
    keywords: ['progreso', 'en progreso', 'haciendo', 'doing', 'curso', 'en curso', 'trabajando', 'actual'],
    listTerms: ['progreso', 'doing', 'curso', 'trabajando', 'actual', 'desarrollo'],
  },
  {
    keywords: ['finalizado', 'finalizadas', 'hecho', 'hechas', 'terminado', 'terminadas', 'done', 'cerrado', 'cerradas', 'completado', 'completadas'],
    listTerms: ['final', 'done', 'hecho', 'terminado', 'cerrado', 'complet'],
  },
  {
    keywords: ['bloqueado', 'bloqueadas', 'impedimento', 'impedimentos', 'blocked'],
    listTerms: ['bloque', 'imped', 'blocked'],
  },
];

let semanticMatches = [];
for (const bucket of semanticBuckets) {
  if (bucket.keywords.some(keyword => q.includes(keyword))) {
    const matches = lists.filter(list => {
      const name = normalize(list.name);
      return bucket.listTerms.some(term => name.includes(term));
    });
    semanticMatches.push(...matches);
  }
}

const dedupe = (items) => {
  const seen = new Set();
  return items.filter(item => {
    if (!item?.id || seen.has(item.id)) return false;
    seen.add(item.id);
    return true;
  });
};

let selected = dedupe([...explicitMatches, ...semanticMatches]);

if (selected.length === 0) {
  selected = lists;
}

return selected.map(list => ({
  json: {
    listId: list.id,
    listName: list.name,
    question: req.question,
    normalizedQuestion: req.normalizedQuestion,
    replyTarget: req.replyTarget,
    isGroup: req.isGroup,
    shouldRespond: req.shouldRespond,
    originalQuestion: req.originalQuestion,
    boardId: req.boardId,
    allowedGroupJid: req.allowedGroupJid,
  },
}));

const req = $("Normalizar entrada").first().json;
const board = $("Trello: tablero").first()?.json || {};
const allLists = $("Trello: listas del tablero").all().map(item => item.json);
const selectedLists = $("Preparar listas para tarjetas").all().map(item => item.json);
const rawCards = $input.all().map(item => item.json).filter(card => card && Object.keys(card).length > 0);

const normalize = (value = '') =>
  String(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();

const q = normalize(req.normalizedQuestion || req.question || '');
const boardName = board.name || 'tu tablero';

const listNameById = new Map(allLists.map(list => [list.id, list.name]));
const selectedListIds = new Set(selectedLists.map(list => list.listId));

const cards = rawCards.map(card => ({
  ...card,
  listName: listNameById.get(card.idList) || card.listName || 'Sin lista',
}));

const cardsByListId = new Map();
for (const list of allLists) {
  cardsByListId.set(list.id, []);
}
for (const card of cards) {
  if (!cardsByListId.has(card.idList)) {
    cardsByListId.set(card.idList, []);
  }
  cardsByListId.get(card.idList).push(card);
}

const totalCards = Array.from(cardsByListId.values()).reduce((acc, items) => acc + items.length, 0);

function truncate(text, max = 180) {
  const value = String(text || '').replace(/\s+/g, ' ').trim();
  if (!value) return '';
  return value.length > max ? `${value.slice(0, max - 1)}…` : value;
}

function bullets(items, max = 12) {
  return items.slice(0, max).map(item => `- ${item}`).join('\n');
}

function numbered(items, max = 8) {
  return items.slice(0, max).map((item, idx) => `${idx + 1}. ${item}`).join('\n');
}

function formatDateES(dateValue) {
  if (!dateValue) return '';
  const date = new Date(dateValue);
  if (Number.isNaN(date.getTime())) return '';
  return date.toLocaleDateString('es-ES');
}

function uniqueById(items) {
  const seen = new Set();
  return items.filter(item => {
    if (!item?.id || seen.has(item.id)) return false;
    seen.add(item.id);
    return true;
  });
}

function formatCard(card) {
  const parts = [card.name];

  const labelNames = Array.isArray(card.labels)
    ? card.labels.map(label => label.name || label.color).filter(Boolean)
    : [];

  if (labelNames.length) {
    parts.push(`etiquetas: ${labelNames.slice(0, 3).join(', ')}`);
  }

  if (card.due) {
    const due = formatDateES(card.due);
    if (due) {
      parts.push(`vence ${due}`);
    }
  }

  if (card.closed) {
    parts.push('cerrada');
  }

  return parts.join(' · ');
}

function buildCardDetails(card) {
  const lines = [`La tarjeta "${card.name}" está en la lista "${card.listName}".`];

  if (card.due) {
    const due = formatDateES(card.due);
    if (due) {
      lines.push(`Vence el ${due}.`);
    }
  }

  if (Array.isArray(card.labels) && card.labels.length) {
    const labels = card.labels.map(label => label.name || label.color).filter(Boolean).slice(0, 8);
    if (labels.length) {
      lines.push(`Etiquetas: ${labels.join(', ')}.`);
    }
  }

  if (card.desc) {
    lines.push(`Descripción: ${truncate(card.desc, 220)}`);
  }

  const url = card.shortUrl || card.url;
  if (url) {
    lines.push(`Enlace: ${url}`);
  }

  return lines.join(' ');
}

function detectMatchedLists() {
  const explicitMatches = allLists.filter(list => q.includes(normalize(list.name)));
  if (explicitMatches.length) return explicitMatches;

  const semantic = [];
  const addMatches = (keywords, terms) => {
    if (keywords.some(keyword => q.includes(keyword))) {
      semantic.push(
        ...allLists.filter(list => {
          const name = normalize(list.name);
          return terms.some(term => name.includes(term));
        }),
      );
    }
  };

  addMatches(
    ['pendiente', 'pendientes', 'backlog', 'por hacer', 'por-hacer', 'todo', 'to do', 'abierto', 'abierta'],
    ['pendiente', 'backlog', 'por hacer', 'por-hacer', 'todo', 'to do', 'abierto', 'idea']
  );
  addMatches(
    ['progreso', 'en progreso', 'haciendo', 'doing', 'curso', 'en curso', 'trabajando', 'actual'],
    ['progreso', 'doing', 'curso', 'trabajando', 'actual', 'desarrollo']
  );
  addMatches(
    ['finalizado', 'finalizadas', 'hecho', 'hechas', 'terminado', 'terminadas', 'done', 'cerrado', 'cerradas', 'completado', 'completadas'],
    ['final', 'done', 'hecho', 'terminado', 'cerrado', 'complet']
  );
  addMatches(
    ['bloqueado', 'bloqueadas', 'impedimento', 'impedimentos', 'blocked'],
    ['bloque', 'imped', 'blocked']
  );

  return uniqueById(semantic);
}

function tokenize(text) {
  return normalize(text)
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean);
}

function extractSearchTokens() {
  const stopwords = new Set([
    'dime','di','que','cual','cuales','el','la','los','las','un','una','unos','unas',
    'de','del','al','y','o','en','por','para','con','sin','mi','mis','tu','tus','su','sus',
    'tablero','board','lista','listas','tarjeta','tarjetas','card','cards','tarea','tareas',
    'hay','tengo','tenemos','muestrame','muéstrame','ver','mostrar','ensename','enséñame',
    'buscar','busca','encuentra','detalle','detalles','estado','general','trabajos','trabajo',
    'pendiente','pendientes','progreso','finalizado','finalizadas','hecho','hechas','terminado','terminadas',
    'bloqueado','bloqueadas','checklist','checklists','adjunto','adjuntos','miembro','miembros',
    'nombre','nombres','exacto','exacta','sobre','quiero','favor','donde','dónde','esta','está',
    'abre','abrir','link','enlace','url','lleva','llevame','llévame','ensena','enseña',
    'numero','número','num','opcion','opción','opciones','resultado','resultados',
    'etiqueta','etiquetas','fecha','fechas','vence','vencen','vencimiento','vencimientos',
    'hoy','mañana','manana','ayer','semana','mes','esta','este','atrasadas','atrasados',
    'ayuda','comandos','como','cómo'
  ]);

  let working = q;
  for (const list of allLists) {
    const listName = normalize(list.name);
    if (listName) {
      working = working.replace(listName, ' ');
    }
  }

  return tokenize(working).filter(token => !stopwords.has(token) && token.length > 1);
}

function getDateKeywords(dateValue) {
  if (!dateValue) return [];
  const date = new Date(dateValue);
  if (Number.isNaN(date.getTime())) return [];

  const today = new Date();
  const startToday = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const target = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const diffDays = Math.round((target - startToday) / 86400000);

  const parts = [
    target.toLocaleDateString('es-ES'),
    `${target.getFullYear()}-${String(target.getMonth() + 1).padStart(2, '0')}-${String(target.getDate()).padStart(2, '0')}`,
    String(target.getFullYear()),
    String(target.getDate()),
  ];

  if (diffDays === 0) parts.push('hoy');
  if (diffDays === 1) parts.push('mañana', 'manana');
  if (diffDays === -1) parts.push('ayer');
  if (diffDays >= 0 && diffDays <= 7) parts.push('esta semana');
  if (diffDays > 7 && diffDays <= 31) parts.push('este mes');

  return parts.map(normalize).filter(Boolean);
}

function cardSearchHaystack(card) {
  const labels = Array.isArray(card.labels)
    ? card.labels.map(label => `${normalize(label.name || '')} ${normalize(label.color || '')}`).join(' ')
    : '';
  const dueTerms = getDateKeywords(card.due).join(' ');
  const basic = `${normalize(card.name)} ${normalize(card.desc || '')} ${normalize(card.listName || '')} ${labels} ${dueTerms}`;
  return normalize(basic);
}

function filterByTokens(cardsToFilter, tokens) {
  if (!tokens.length) return cardsToFilter;
  return cardsToFilter
    .map(card => {
      const haystack = cardSearchHaystack(card);
      const score = tokens.reduce((acc, token) => acc + (haystack.includes(token) ? 1 : 0), 0);
      return { card, score };
    })
    .filter(item => item.score > 0)
    .sort((a, b) => b.score - a.score || a.card.name.localeCompare(b.card.name))
    .map(item => item.card);
}

function filterByLabels(cardsToFilter) {
  const wantsLabels = /\betiqueta\b|\betiquetas\b/.test(q);
  if (!wantsLabels) return cardsToFilter;

  const tokens = extractSearchTokens();
  if (!tokens.length) {
    return cardsToFilter.filter(card => Array.isArray(card.labels) && card.labels.length > 0);
  }

  return cardsToFilter.filter(card => {
    const labelText = Array.isArray(card.labels)
      ? card.labels.map(label => `${normalize(label.name || '')} ${normalize(label.color || '')}`).join(' ')
      : '';
    return tokens.some(token => labelText.includes(token));
  });
}

function filterByDates(cardsToFilter) {
  const wantsToday = /\bhoy\b/.test(q);
  const wantsTomorrow = /\bmañana\b|\bmanana\b/.test(q);
  const wantsWeek = /\besta semana\b/.test(q);
  const wantsMonth = /\beste mes\b/.test(q);
  const wantsOverdue = /\batrasad|\bvencid/.test(q);
  const wantsWithDate = /\bcon fecha\b|\bfecha\b|\bfechas\b|\bvencimiento\b|\bvencen\b|\bvence\b/.test(q);

  if (!(wantsToday || wantsTomorrow || wantsWeek || wantsMonth || wantsOverdue || wantsWithDate)) {
    return cardsToFilter;
  }

  const today = new Date();
  const startToday = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const endWeek = new Date(startToday);
  endWeek.setDate(endWeek.getDate() + 7);
  const endMonth = new Date(startToday);
  endMonth.setMonth(endMonth.getMonth() + 1);

  return cardsToFilter.filter(card => {
    if (!card.due) return false;
    const due = new Date(card.due);
    if (Number.isNaN(due.getTime())) return false;

    const dueDay = new Date(due.getFullYear(), due.getMonth(), due.getDate());
    const diffDays = Math.round((dueDay - startToday) / 86400000);

    if (wantsToday) return diffDays === 0;
    if (wantsTomorrow) return diffDays === 1;
    if (wantsWeek) return dueDay >= startToday && dueDay <= endWeek;
    if (wantsMonth) return dueDay >= startToday && dueDay <= endMonth;
    if (wantsOverdue) return dueDay < startToday;
    if (wantsWithDate) return true;
    return true;
  });
}

function getMemoryKey() {
  return `${req.remoteJid || req.replyTarget}::${req.participant || 'grupo'}`;
}

function getStoredSearches() {
  const store = $getWorkflowStaticData('global');
  if (!store.cardSearches) {
    store.cardSearches = {};
  }
  return store.cardSearches;
}

function saveSearchResults(results) {
  const searches = getStoredSearches();
  const key = getMemoryKey();
  searches[key] = {
    timestamp: Date.now(),
    results: results.slice(0, 8).map(card => ({
      id: card.id,
      name: card.name,
      listName: card.listName,
      due: card.due || null,
      desc: card.desc || '',
      labels: Array.isArray(card.labels) ? card.labels : [],
      shortUrl: card.shortUrl || '',
      url: card.url || '',
      closed: !!card.closed,
    })),
  };
}

function getSavedResultByIndex(index) {
  const searches = getStoredSearches();
  const key = getMemoryKey();
  const memory = searches[key];

  if (!memory || !Array.isArray(memory.results)) {
    return { error: 'missing' };
  }

  const ageMs = Date.now() - Number(memory.timestamp || 0);
  const maxAgeMs = 12 * 60 * 60 * 1000;
  if (ageMs > maxAgeMs) {
    delete searches[key];
    return { error: 'expired' };
  }

  if (index < 1 || index > memory.results.length) {
    return { error: 'out_of_range', total: memory.results.length };
  }

  return { card: memory.results[index - 1], total: memory.results.length };
}

function findNumberedFollowupIndex() {
  const patterns = [
    /\b(?:abre|abrir|detalle|detalles|muestrame|muéstrame|ensename|enséñame|link|enlace|url|abreme|ábreme)\s+(?:la|el)?\s*(\d{1,2})\b/,
    /\b(?:la|el)\s+(\d{1,2})\b/,
    /^\s*(\d{1,2})\s*$/
  ];

  for (const pattern of patterns) {
    const match = q.match(pattern);
    if (match) return Number(match[1]);
  }
  return null;
}

function buildHelpMessage() {
  const whitelistLine = req.hasWhitelist
    ? 'Solo responde a los usuarios incluidos en la lista blanca.'
    : 'Ahora mismo responde a cualquier usuario del grupo autorizado.';

  return [
    'Comandos disponibles:',
    '- tr tablero',
    '- tr listas',
    '- tr tarjetas de en progreso',
    '- tr busca factura',
    '- tr tarjetas con etiqueta urgente',
    '- tr tarjetas que vencen hoy',
    '- tr tarjetas en progreso con etiqueta urgente que vencen hoy',
    '- tr abre la 2',
    '',
    'También puedes combinar filtros por lista + etiqueta + fecha.',
    whitelistLine,
  ].join('\n');
}

function buildGuidedError() {
  if (/\betiqueta\b|\betiquetas\b/.test(q) && /\bfecha\b|\bfechas\b|\bhoy\b|\bmañana\b|\bmanana\b|\bsemana\b|\bmes\b|\bvence\b|\bvencen\b/.test(q)) {
    return 'No he encontrado resultados con esa combinación. Prueba algo como: tr tarjetas en progreso con etiqueta urgente que vencen hoy.';
  }
  if (/\betiqueta\b|\betiquetas\b/.test(q)) {
    return 'No he encontrado resultados con esa etiqueta. Prueba algo como: tr tarjetas con etiqueta urgente.';
  }
  if (/\bfecha\b|\bfechas\b|\bhoy\b|\bmañana\b|\bmanana\b|\bsemana\b|\bmes\b|\bvence\b|\bvencen\b|\batrasad|\bvencid/.test(q)) {
    return 'No he encontrado tarjetas para esa fecha. Prueba con: tr tarjetas que vencen hoy o tr tarjetas atrasadas.';
  }
  if (/\blista\b|\blistas\b|\bprogreso\b|\bpendiente\b|\bhecho\b|\bfinalizado\b/.test(q)) {
    return 'No he encontrado esa lista o no hay tarjetas que coincidan. Prueba con: tr listas o tr tarjetas de en progreso.';
  }
  if (/\bbusca\b|\btarjeta\b|\btarea\b|\bdetalle\b/.test(q)) {
    return 'No he encontrado esa tarjeta. Prueba con: tr busca [nombre de tarjeta].';
  }
  return 'No se puede realizar tu consulta en estos momentos. Prueba con tr ayuda para ver ejemplos.';
}

const asksHelp = /^ayuda$|^help$|^comandos$|^que puedes hacer$|^qué puedes hacer$/.test(q) || /\bayuda\b|\bcomandos\b/.test(q);
const asksBoard = /\b(tablero|board)\b/.test(q);
const asksLists = /\b(lista|listas|columnas|column)\b/.test(q);
const asksCards = /\b(tarjeta|tarjetas|card|cards|tarea|tareas|pendiente|pendientes|progreso|bloquead|finalizad|hech|terminad|detalle|detalles|etiqueta|etiquetas|fecha|fechas|vence|vencen)\b/.test(q);
const asksCount = /\b(cuantas|cuantos|cuántas|cuántos|numero|número|total|cuenta)\b/.test(q);
const asksSummary = /\b(resumen|estado|general|todo|todas|todas las|que hay|qué hay)\b/.test(q);
const asksSpecificCard = /\b(detalle|detalles|buscar|busca|encuentra|tarjeta|tarea|donde|dónde|esta|está|abre|abrir|link|enlace|url|lleva|llévame|enseña|enséñame)\b/.test(q);
const asksLabels = /\betiqueta\b|\betiquetas\b/.test(q);
const asksDates = /\bfecha\b|\bfechas\b|\bvence\b|\bvencen\b|\bvencimiento\b|\bhoy\b|\bmañana\b|\bmanana\b|\besta semana\b|\beste mes\b|\batrasad|\bvencid/.test(q);

let output = '';

if (!req.question) {
  output = 'No se puede realizar tu consulta en estos momentos. Prueba con tr ayuda.';
} else if (asksHelp) {
  output = buildHelpMessage();
} else {
  const followupIndex = findNumberedFollowupIndex();

  if (followupIndex !== null) {
    const saved = getSavedResultByIndex(followupIndex);
    if (saved.card) {
      output = buildCardDetails(saved.card);
    } else if (saved.error === 'missing') {
