}

function findDocumentMessage(message) {
  if (!message || typeof message !== 'object') return null;
  if (message.documentMessage) return message.documentMessage;
  if (message.documentWithCaptionMessage?.message?.documentMessage) return message.documentWithCaptionMessage.message.documentMessage;
  if (message.viewOnceMessage?.message?.documentMessage) return message.viewOnceMessage.message.documentMessage;
  if (message.ephemeralMessage?.message?.documentMessage) return message.ephemeralMessage.message.documentMessage;
  if (message.ephemeralMessage?.message?.documentWithCaptionMessage?.message?.documentMessage) {
    return message.ephemeralMessage.message.documentWithCaptionMessage.message.documentMessage;
  }
  return null;
}

